class Solution:
    def minimumLines(self, stockPrices: List[List[int]]) -> int:
        stockPrices.sort()
        n = len(stockPrices)
        if n < 3:
            return n - 1
        ans = 1
        for i in range(1, n - 1):
            dx1 = stockPrices[i][0] - stockPrices[i - 1][0]
            dy1 = stockPrices[i][1] - stockPrices[i - 1][1]
            dx2 = stockPrices[i + 1][0] - stockPrices[i][0]
            dy2 = stockPrices[i + 1][1] - stockPrices[i][1]
            if dx1 * dy2 != dx2 * dy1:
                ans += 1
        return ans

