        stockPrices.sort()
        n = len(stockPrices)
        if n < 3:
            return n - 1
        ans = 1
        prev = None
        for i in range(1, n):
            s = (stockPrices[i][1] - stockPrices[i - 1][1]) / (stockPrices[i][0] - stockPrices[i - 1][0])
